/**
 * Who reports to one manager, drawn as a tree.
 *
 * Shared by the two places that ask it, because they are the same question
 * asked from different ends: on User Access, "this account manages whom?",
 * and on the org chart, "what does the organisation look like?". One
 * component means the answer cannot differ between them.
 *
 * Inactive coaches are kept and marked rather than dropped. A squad of twelve
 * that shows eight is a squad somebody will re-count by hand.
 */
const SquadTree = ({
  squad, scope, managerName, managerUnknown = false, compact = false,
  // Moving coaches between squads. Absent on the read-only uses, so the
  // same component serves both without a second copy to keep in step.
  canMove = false, draggingId = null, isOver = false,
  onPickUp, onPutDown, onDragOverSquad, onDragLeaveSquad,
  // Picking several at once. Eighteen people moved one drag at a time is
  // eighteen confirmations and eighteen chances to drop one on the wrong
  // squad.
  selectedIds = null, onToggleOne, onToggleSquad
}) => {
  const selectable = canMove && Array.isArray(selectedIds);
  const isPicked = (id) => selectable && selectedIds.includes(id);
  const pickedHere = selectable ? squad.filter(c => selectedIds.includes(c.id)).length : 0;
  const active = squad.filter(c => c.status === 'Active');
  const rest = squad.filter(c => c.status !== 'Active');

  return (
    <div
      className={`orgchart ${compact ? 'is-compact' : ''} ${canMove ? 'can-move' : ''} ${isOver ? 'is-over' : ''}`}
      onDragOver={canMove ? (e) => { e.preventDefault(); onDragOverSquad?.(scope?.id); } : undefined}
      onDragLeave={canMove ? () => onDragLeaveSquad?.(scope?.id) : undefined}
      onDrop={canMove ? (e) => {
        e.preventDefault();
        onPutDown?.(e.dataTransfer.getData('text/plain'), scope?.id);
      } : undefined}
    >
      <div className={`org-node org-manager${selectable ? ' is-selectable' : ''}`}>
        {selectable && squad.length > 0 && (
          <label
            className="org-pick org-pick-all"
            title={pickedHere === squad.length ? 'Clear this squad' : 'Pick everyone here'}
          >
            <input
              type="checkbox"
              checked={pickedHere === squad.length && squad.length > 0}
              // Some but not all: the box says "partly", which is the only
              // honest third state for a list this long.
              ref={el => { if (el) el.indeterminate = pickedHere > 0 && pickedHere < squad.length; }}
              onChange={() => onToggleSquad?.(squad.map(c => c.id),
                pickedHere !== squad.length)}
            />
          </label>
        )}
        <strong>{managerName || scope?.label || scope?.id || 'Unassigned'}</strong>
        {/* Who holds the squad comes from the accounts list, which only an
            admin may read. Saying "no account holds this squad" to somebody
            who simply cannot see the accounts would be a confident lie, so
            when it is unknown nothing is claimed either way. */}
        {/* The manager's name is the heading above: "RM_01 — S&C" is how a
            squad is keyed, not what anybody calls it, and someone reading an
            org chart is looking for a person. The key shows only where there
            is no name to show instead, because a squad you can drop somebody
            onto still has to be identifiable. */}
        {!managerName && !managerUnknown && (
          <small className="org-warn">no account holds this squad</small>
        )}
        <span className="org-count">
          {active.length} active{rest.length ? ` · ${rest.length} not` : ''}
        </span>
      </div>

      {squad.length === 0 ? (
        <p className="org-empty">Nobody reports here yet.</p>
      ) : (
        <ul className="org-leaves">
          {/* The item carries the connector, a box inside it carries the
              card. One element doing both puts the tree line inside the box
              it is supposed to be pointing at. */}
          {[...active, ...rest].map(c => (
            <li key={c.id} className="org-leaf">
              <div
                className={`org-node org-coach ${c.status === 'Active' ? '' : 'is-off'}`
                  + `${canMove ? ' is-draggable' : ''}${draggingId === c.id ? ' is-dragging' : ''}`
                  + `${isPicked(c.id) ? ' is-picked' : ''}${selectable ? ' is-selectable' : ''}`}
                draggable={canMove || undefined}
                onDragStart={canMove ? (e) => {
                  e.dataTransfer.setData('text/plain', c.id);
                  e.dataTransfer.effectAllowed = 'move';
                  onPickUp?.(c.id);
                } : undefined}
                onDragEnd={canMove ? () => onPickUp?.(null) : undefined}
                title={canMove
                  ? (isPicked(c.id)
                      ? 'Dragging this moves everyone picked'
                      : `Drag ${c.name} onto another squad to move them`)
                  : undefined}
              >
                {selectable && (
                  <label className="org-pick" title={`Pick ${c.name}`}>
                    <input
                      type="checkbox"
                      checked={isPicked(c.id)}
                      onChange={() => onToggleOne?.(c.id)}
                    />
                  </label>
                )}
                <strong>{c.name}</strong>
                <small>{c.id}{c.coach_category ? ` · ${c.coach_category}` : ''}</small>
                {/* Somebody can be both: a coach on the roster and the account
                    that manages a squad. Without saying so, their card in the
                    unassigned column reads as an oversight when it is simply
                    the other half of the same person. */}
                {c.managesSquad && (
                  <span className="org-status org-manages">manages {c.managesSquad}</span>
                )}
                {/* Their record points at a squad, but nobody holds it — so
                    they are here rather than under a heading that approves
                    nothing. Said on the card so the fact is not lost with the
                    card that used to show it. */}
                {c.strandedFrom && (
                  <span className="org-status org-stranded">listed under {c.strandedFrom}</span>
                )}
                {c.status !== 'Active' && <span className="org-status">{c.status}</span>}
              </div>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

const rupees = (n) => `₹${Math.round(Number(n) || 0).toLocaleString('en-IN')}`;

// Who the slip is from. One place, because the name appears in the letterhead
// and again in the footer, and a payslip that disagrees with itself about the
// paying entity is not a document anyone can file.
const SLIP_COMPANY = {
  name: 'HASEL HEALTH AND WELLNESS PRIVATE LIMITED',
  gstin: '21AAGCH5082C1Z1',
  address: [
    '206, Lumbini Enclave, Niladri Vihar',
    'Bhubaneswar, Odisha 751021, India'
  ]
};

// The two brands a coach can be paid under. Same company and the same GSTIN —
// what changes is the mark at the head of the slip, because a HOP coach's
// payslip carrying the HB+ logo is the kind of thing that gets a document
// handed back.
const SLIP_BRANDS = {
  'HB+': { label: 'HB+', logo: '/logo.svg' },
  'HOP': { label: 'HOP', logo: '/logo-hop.svg' }
};
const BRAND_OPTIONS = Object.keys(SLIP_BRANDS);

/**
 * Which brand a coach is paid under.
 *
 * The brand set on the coach wins. Where none has been set — every coach,
 * until the column is filled in — it falls back to the policy variant's
 * property, which is where the distinction already lived: a HOP variant is
 * written "HOP Studio / Home Visit". That keeps existing coaches on the right
 * letterhead without anyone having to touch them one by one, while leaving the
 * field free to override it where the variant does not tell the truth.
 */
const brandOf = (coach, variantConfig) => {
  const set = coach?.brand;
  if (set && SLIP_BRANDS[set]) return set;
  return String(variantConfig?.property || '').trim().toUpperCase().startsWith('HOP')
    ? 'HOP' : 'HB+';
};

// The mark used on a salary slip when no logo file has been supplied. Inline
// SVG rather than a request, so it renders in a print preview and in a saved
// PDF without the network being involved.
const SLIP_WORDMARK = "data:image/svg+xml;utf8," + encodeURIComponent(
  '<svg xmlns="http://www.w3.org/2000/svg" width="150" height="44" viewBox="0 0 150 44">' +
  '<text x="0" y="33" font-family="Helvetica,Arial,sans-serif" font-size="32" ' +
  'font-weight="700" fill="#747440">HB+</text></svg>');

/**
 * A period's settled score for a coach: the stored value (which the score card
 * editor keeps in step, overrides included) falling back to a fresh calculation.
 */
const resolvePeriodScore = (coach, record, vConfig) => {
  const score = record.hb_score !== undefined && record.hb_score !== null
    ? record.hb_score
    : computeHBPlusScore(coach, record, vConfig).hbScore;
  return { score, band: record.band || getPerformanceBand(score).label };
};

/**
 * Monthly Pay Calculator — the sheet's "fill yellow cells only" form. Inputs are
 * editable; the breakdown below is driven by computeMonthlyPay so it can never
 * drift from the payroll the rest of the app produces.
 */
function PayCalculator({ variants, seed, onSeedChange, coachOptions, selectedCoachId, onCoachChange, lockCoach, periodOptions, onPeriodChange, canOverridePay = false, onSavePayOverrides, onCommitModel }) {
  const [coachName, setCoachName] = useState(seed?.coachName ?? "");
  const [variantId, setVariantId] = useState(seed?.variantId ?? "V1");
  const [category, setCategory] = useState(seed?.category ?? "Fixed");
  const [score, setScore] = useState(seed?.score ?? 0);
  const [sessions, setSessions] = useState(seed?.sessions ?? 0);
  const [nightSessions, setNightSessions] = useState(seed?.nightSessions ?? 0);
  const [streak, setStreak] = useState(seed?.streak ?? 0);
  const [consistency, setConsistency] = useState(seed?.consistency ?? "NO");
  const [orgWorkPay, setOrgWorkPay] = useState(seed?.orgWorkPay ?? 0);
  const [penalties, setPenalties] = useState(seed?.penalties ?? 0);
  const [missedSessions, setMissedSessions] = useState(seed?.missedSessions ?? 0);
  const [lopDays, setLopDays] = useState(seed?.lopDays ?? 0);
  // The change-set the save bar was last dismissed for. Keyed rather than a
  // plain boolean: dismissing it should quiet this edit, not every edit after.
  // Rupees of this month's penalty forgiven. Kept apart from the incidents:
  // they keep their amounts and their occurrence numbers, and only what is
  // taken this month moves.
  const [penaltyWaiver, setPenaltyWaiver] = useState(seed?.penaltyWaiver ?? 0);
  const [savePromptHiddenFor, setSavePromptHiddenFor] = useState("");
  const [baseOverride, setBaseOverride] = useState(seed?.baseOverride ?? "");
  // Blank means "use the band's rate"; a number overrides it for this model.
  const [rateOverride, setRateOverride] = useState(seed?.rateOverride ?? "");
  // Blank means "use the band's threshold"; a number sets it for this month.
  const [thresholdOverride, setThresholdOverride] = useState(seed?.thresholdOverride ?? "");
  // Sessions taken outside the hours the coach published. Recorded, not
  // derived: the threshold cannot tell you which sessions fell outside them.
  const [beyondSessions, setBeyondSessions] = useState(seed?.beyondSessions ?? 0);
  // Blank means the flat default; a number sets this coach's own rate.
  const [beyondRate, setBeyondRate] = useState(seed?.beyondRate ?? "");
  // Both pay fields start locked. Taking one over is a deliberate act, as it is
  // for a calculated cell on the score card.
  const [unlockedPay, setUnlockedPay] = useState({ rate: false, base: false });
  // The incidents behind the penalty figure. Derived from the seed rather than
  // held in state, so they follow the coach and period without a second sync.
  const [penaltyOpen, setPenaltyOpen] = useState(false);

  // Re-seed when the caller points the calculator somewhere new — a different
  // coach or period — AND when the record it is already showing changes. Keying
  // this on the coach/period alone left the calculator holding stale figures
  // after a score card was edited underneath it, since the key never moved.
  const seedSignature = seed
    ? [
        seed.key, seed.coachName, seed.variantId, seed.category, seed.score,
        seed.sessions, seed.nightSessions, seed.streak, seed.consistency,
        seed.orgWorkPay, seed.penalties, seed.missedSessions, seed.lopDays,
        seed.baseOverride, seed.rateOverride, seed.thresholdOverride,
        seed.beyondSessions, seed.beyondRate
      ].join('|')
    : '';
  useEffect(() => {
    if (!seed) return;
    setCoachName(seed.coachName ?? "");
    setVariantId(seed.variantId ?? "V1");
    setCategory(seed.category ?? "Fixed");
    setScore(seed.score ?? 0);
    setSessions(seed.sessions ?? 0);
    setNightSessions(seed.nightSessions ?? 0);
    setStreak(seed.streak ?? 0);
    setConsistency(seed.consistency ?? "NO");
    setOrgWorkPay(seed.orgWorkPay ?? 0);
    setPenalties(seed.penalties ?? 0);
    setPenaltyWaiver(seed.penaltyWaiver ?? 0);
    setMissedSessions(seed.missedSessions ?? 0);
    setLopDays(seed.lopDays ?? 0);
    setBaseOverride(seed.baseOverride ?? "");
    setRateOverride(seed.rateOverride ?? "");
    setThresholdOverride(seed.thresholdOverride ?? "");
    setBeyondSessions(seed.beyondSessions ?? 0);
    setBeyondRate(seed.beyondRate ?? "");
    // A different coach or period is a different pay decision, so both lock again.
    setUnlockedPay({ rate: false, base: false });
  }, [seedSignature]);

  const vConfig = variants.find(v => v.id === variantId) || variants[0];
  if (!vConfig) return null;

  const numericScore = Math.min(90, Math.max(0, Number(score) || 0));
  const band = getPerformanceBand(numericScore);
  const rates = vConfig.rates[category]?.[band.label] || {};

  // A synthetic coach + month record: consistency is a yes/no input here rather
  // than something derived, so attendance is forced to match the choice and the
  // penalty total is applied at the end instead of through a violations list.
  // The override travels on the coach, so every category honours it the same
  // way — including Fixed, whose rate is otherwise derived from its own pay.
  const bandLabels = PAY_BANDS.map(b => b.label);
  const nextBandLabel = (() => {
    const i = bandLabels.indexOf(band.label);
    return i >= 0 && i < bandLabels.length - 1 ? bandLabels[i + 1] : null;
  })();
  const forecastFor = (label) => {
    const r = label ? vConfig.rates[category]?.[label] : null;
    if (!r) return null;
    const base = category === 'Fixed' ? r.std_fixed : r.min_fixed;
    // A Fixed coach's session rate comes from their own monthly pay, not the
    // band's column, so the forecast has to be derived the same way.
    const rate = category === 'Fixed' ? fixedPerSessionRate(base) : r.per_session;
    // The band is a range, not a point. For a Fixed coach the session rate
    // follows the salary, so its range is derived from the salary's ends;
    // Flexi and Flexi-Fixed are paid the band's own column, which is a point.
    const lo = r.min_fixed ?? 0;
    const hi = r.max_fixed ?? lo;
    return {
      label,
      base: base ?? 0,
      rate: rate ?? 0,
      salaryLo: lo,
      salaryHi: hi,
      rateLo: category === 'Fixed' ? fixedPerSessionRate(lo) : (r.per_session ?? 0),
      rateHi: category === 'Fixed' ? fixedPerSessionRate(hi) : (r.per_session ?? 0)
    };
  };
  /**
   * Which inputs have been moved away from what is recorded.
   *
   * Everything on this form is editable, but only the two pay fields save —
   * the rest belong to the score card or the coach profile. Without saying so,
   * a changed figure looks like an edit that simply has not been saved yet,
   * which is the question this screen kept raising.
   */
  const modelledChanges = (() => {
    if (!seed?.coachId) return [];
    const same = (a, b) => String(a ?? '') === String(b ?? '');
    // The fourth column is where the figure really lives; the fifth is the key
    // it writes to when saved. The ones without a key are derived or kept
    // somewhere this screen has no business writing — a score comes from six
    // ratings, a penalty total from the incidents behind it.
    return [
      ['Coach Category', category, seed.category, 'the coach profile', 'category', 'profile'],
      ['HB+ Benchmark Score', score, seed.score, 'the score card', null, null],
      ['Sessions Completed', sessions, seed.sessions, 'the score card — Incentive', 'sessions', 'period'],
      ['Night Sessions', nightSessions, seed.nightSessions, 'the score card — Incentive', 'nightSessions', 'period'],
      ['5-Star Streak', streak, seed.streak, 'the score card — Incentive', 'streak', 'period'],
      ['Missed Sessions', missedSessions, seed.missedSessions ?? 0, 'the score card — Incentive', 'missedSessions', 'period'],
      ['Policy Variant', variantId, seed.variantId, 'the coach profile', 'variantId', 'profile'],
      ['Org Work Pay', orgWorkPay, seed.orgWorkPay, 'the coach page — Org Work', null, null],
      ['Total Penalty', penalties, seed.penalties, 'the Penalties tab', null, null],
      ['Penalty Waived', penaltyWaiver, seed.penaltyWaiver ?? 0, 'this screen', 'penaltyWaiver', 'period'],
      ['Session Threshold', thresholdOverride, seed.thresholdOverride ?? "", 'this screen', 'thresholdOverride', 'period'],
      ['Sessions Beyond Availability', beyondSessions, seed.beyondSessions ?? 0, 'this screen', 'beyondSessions', 'period'],
      ['Beyond-Availability Rate', beyondRate, seed.beyondRate ?? "", 'this screen', 'beyondRate', 'profile']
    ].filter(([, now, was]) => !same(now, was))
     .map(([label, now, was, where, commit, scope]) => ({ label, now, was, where, commit, scope }));
  })();

  /**
   * Commit whatever has been typed, and say what happened.
   *
   * Shared by the banner above the fields and the bar below them: the banner
   * scrolls out of sight the moment anyone starts editing, which is exactly
   * when the button is wanted.
   */
  const saveModelToRecord = () => {
    if (!onCommitModel || !seed?.coachId) return;
    const savable = modelledChanges.filter(c => c.commit);
    const readOnly = modelledChanges.filter(c => !c.commit);
    if (savable.length === 0) return;

    const list = savable.map(c => `• ${c.label}: ${c.was} → ${c.now}`).join('\n');
    const left = readOnly.length
      ? `\n\nNot saved, because they are worked out elsewhere:\n` +
        readOnly.map(c => `• ${c.label} — ${c.where}`).join('\n')
      : '';
    if (!window.confirm(
      `Save to ${seed.periodMonth}?\n\n${list}${left}\n\n` +
      `These stop being a model and become what the coach is paid on.`)) return;

    const res = onCommitModel(seed.coachId, seed.periodMonth,
      Object.fromEntries(savable.map(c => [c.commit, c.now]))) || {};

    window.alert(res.ok
      ? `Saved to ${seed.periodMonth}.\n\n` +
        `${savable.length} figure${savable.length === 1 ? '' : 's'} written to the record, ` +
        `and the score card and payroll now read the same.\n\n` +
        `It reaches the database within a few seconds. If that fails, a red banner ` +
        `appears at the top of the screen saying so — nothing fails silently.`
      : `Not saved — nothing was written.\n\n${res.why || 'The save was refused.'}`);
  };

  const resetToRecorded = () => {
    if (!seed) return;
    setCategory(seed.category ?? 'Fixed');
    setVariantId(seed.variantId ?? 'V1');
    setScore(seed.score ?? 0);
    setSessions(seed.sessions ?? 0);
    setNightSessions(seed.nightSessions ?? 0);
    setStreak(seed.streak ?? 0);
    setMissedSessions(seed.missedSessions ?? 0);
    setLopDays(seed.lopDays ?? 0);
    setOrgWorkPay(seed.orgWorkPay ?? 0);
    setPenalties(seed.penalties ?? 0);
    setPenaltyWaiver(seed.penaltyWaiver ?? 0);
    setThresholdOverride(seed.thresholdOverride ?? "");
    setBeyondSessions(seed.beyondSessions ?? 0);
    setBeyondRate(seed.beyondRate ?? "");
  };

  const forecastNow = forecastFor(band.label);
  const against = (actual, lo, hi) => {
    const v = Number(actual) || 0;
    if (!lo && !hi) return null;
    if (v < lo) return { state: 'under', label: `${rupees(lo - v)} below` };
    if (v > hi) return { state: 'over', label: `${rupees(v - hi)} above` };
    return { state: 'within', label: 'within range' };
  };
  const forecastNext = forecastFor(nextBandLabel);

  const rateOverrideNum = rateOverride !== "" && Number.isFinite(Number(rateOverride))
    ? Math.max(0, Number(rateOverride))
    : null;

  const syntheticCoach = {
    id: "CALC",
    coach_category: category,
    variant_id: vConfig.id,
    ...(baseOverride !== "" && category === "Fixed" ? { fixed_salary_override: Number(baseOverride) } : {}),
    ...(baseOverride !== "" && category === "Flexi-Fixed" ? { flexi_fixed_base_salary: Number(baseOverride) } : {}),
    ...(rateOverrideNum !== null ? { per_session_override: rateOverrideNum } : {}),
    ...(beyondRate !== "" && Number(beyondRate) > 0
      ? { beyond_availability_rate_override: Number(beyondRate) } : {})
  };
  const thresholdOverrideNum = thresholdOverride !== "" && Number.isFinite(Number(thresholdOverride))
    ? Math.max(0, Math.floor(Number(thresholdOverride)))
    : null;

  const syntheticMonth = {
    ...(thresholdOverrideNum !== null ? { threshold_override: thresholdOverrideNum } : {}),
    beyond_availability_sessions: Number(beyondSessions) || 0,
    lop_days: Number(lopDays) || 0,
    missed_sessions: Number(missedSessions) || 0,
    sessions_completed: Number(sessions) || 0,
    night_sessions: Number(nightSessions) || 0,
    five_star_streak: Number(streak) || 0,
    attendance_pct: consistency === "YES" ? 100 : 0
  };
  const orgItems = isOrgWorkEligible(category) && Number(orgWorkPay) > 0
    ? [{ amount: Number(orgWorkPay) }]
    : [];

  const pay = computeMonthlyPay(syntheticCoach, syntheticMonth, { hbScore: numericScore }, [], vConfig, orgItems);
  // What one day off costs, for the line that shows the arithmetic. Declared
  // here rather than above because it divides `pay`, which does not exist yet
  // up there — and a render reaches these in order.
  const lopPerDayHere = Math.round((pay.basePay / 26) * 100) / 100;
  // Forgiving money is a pay decision, so it needs the same permission as
  // saving one — otherwise the field invites an edit that cannot be kept.
  const canWaive = Boolean(onCommitModel && seed?.coachId);
  const penaltyTotal = Number(penalties) || 0;
  // Clamped to what was actually charged. Waiving more than that would turn a
  // penalty into a payment.
  const waived = Math.min(Math.max(Number(penaltyWaiver) || 0, 0), penaltyTotal);
  const penaltyCharged = Math.round((penaltyTotal - waived) * 100) / 100;
  const grossPay = Math.round((pay.grossPay - penaltyCharged) * 100) / 100;
  // Section 194J: TDS on professional or technical fees, withheld at source.
  // Withheld in whole rupees, as on the payslip.
  const incomeTax = Math.round(grossPay * TDS_194J_RATE);
  const netPay = Math.round((grossPay - incomeTax) * 100) / 100;

  const requestPayEdit = (key, label, standard) => {
    if (unlockedPay[key]) return;
    const proceed = window.confirm(
      `"${label}" comes from the band rate (${standard}).\n\n` +
      `Overriding it changes what this coach is paid for the month. Do you want to edit it?`
    );
    if (!proceed) return;
    setUnlockedPay(prev => ({ ...prev, [key]: true }));
  };

  // Where a pay figure came from. Three figures look identical on screen — one
  // set for this month, one carried from an earlier month, and the band's own
  // — and which it is decides whether editing here changes anything.
  const paySourceHint = (from, unlocked) => {
    if (unlocked) return "leave blank to fall back to the band rate";
    if (!from || from === 'band') {
      return canOverridePay ? "band rate — click to set" : "band rate, nothing set";
    }
    if (from === 'month') {
      return canOverridePay ? "set for this month — click to change" : "set for this month";
    }
    if (from === 'profile') {
      return canOverridePay ? "set on the coach profile — click to change" : "set on the coach profile";
    }
    return canOverridePay ? `carried from ${from} — click to change` : `carried from ${from}`;
  };

  const payLock = (key, label, standard, current) => (
    <button
      type="button"
      className="dynamic-lock-btn"
      title={`From the band rate — click to override (${standard})`}
      onClick={() => requestPayEdit(key, label, standard)}
    >
      <span>{current}</span>
      <i className="bx bx-lock-alt"></i>
    </button>
  );

  const inputRow = (label, control, hint) => (
    <tr key={label}>
      <td className="calc-label">{label}{hint && <span className="calc-hint">{hint}</span>}</td>
      <td className="calc-input-cell">{control}</td>
    </tr>
  );

  const outputRow = (label, value, hint, strong) => (
    <tr key={label} className={strong ? 'calc-total-row' : ''}>
      <td className="calc-label">{label}{hint && <span className="calc-hint">{hint}</span>}</td>
      <td className="calc-output-cell">{value}</td>
    </tr>
  );

  const num = (value, setter, max) => (
    <input
      type="number" min="0" max={max} step="any"
      className="calc-input"
      value={value}
      onChange={(e) => { setter(e.target.value); onSeedChange?.(); }}
    />
  );

  // A deduction with no explanation is the one line on a payslip people
  // dispute, so the Penalty row opens into the incidents it is made of: the
  // date, what happened, which occurrence it was, and what each one cost.
  const penaltyItems = seed?.penaltyItems ?? [];
  const penaltyOtherCount = seed?.penaltyOtherCount ?? 0;
  const recordedPenalty = penaltyItems
    .filter(isPenaltyChargeable)
    .reduce((sum, v) => sum + (Number(v.penalty_amount) || 0), 0);
  // Penalty is an editable input, so the figure on screen can be moved away
  // from what the incidents add up to. Saying so beats quietly disagreeing.
  const penaltyEdited = penaltyItems.length > 0
    && Math.round(penaltyTotal) !== Math.round(recordedPenalty);

  const penaltyRow = () => {
    const rows = [
      <tr key="penalty">
        <td className="calc-label">
          {penaltyItems.length > 0 ? (
            <button
              type="button"
              className="calc-penalty-toggle"
              aria-expanded={penaltyOpen}
              onClick={() => setPenaltyOpen(open => !open)}
            >
              <i className={`bx ${penaltyOpen ? 'bx-chevron-down' : 'bx-chevron-right'}`}></i>
              Penalty (₹)
              <span className="calc-hint">
                {penaltyItems.length} incident{penaltyItems.length === 1 ? '' : 's'} — click to see {penaltyItems.length === 1 ? 'it' : 'them'}
              </span>
            </button>
          ) : (
            <>
              Penalty (₹)
              <span className="calc-hint">
                {seed?.periodRange
                  ? `no incidents dated ${seed.periodRange}`
                  : 'not seeded from a coach — key a figure in on the left'}
                {penaltyOtherCount > 0 && ` · this coach has ${penaltyOtherCount} incident${penaltyOtherCount === 1 ? '' : 's'} outside these dates`}
              </span>
            </>
          )}
        </td>
        <td className="calc-output-cell">− {rupees(penaltyTotal)}</td>
      </tr>
    ];

    // What was waived, and what that leaves. Both are stated here and keyed
    // in on the input side — nothing on this half of the screen is typed
    // into, so a figure read off it is always one the calculator worked out.
    if (penaltyTotal > 0 && canWaive) {
      if (waived > 0) {
        rows.push(
          <tr key="penalty-waived">
            <td className="calc-label">
              Penalty Waived (₹)
              <span className="calc-hint">
                entered on the left — the incidents keep their amounts and their place on the ladder
              </span>
            </td>
            <td className="calc-output-cell">− {rupees(waived)}</td>
          </tr>
        );
        rows.push(
          <tr key="penalty-charged">
            <td className="calc-label">
              Penalty Charged (₹)
              <span className="calc-hint">
                what actually comes off this month, after {rupees(waived)} waived
              </span>
            </td>
            <td className="calc-output-cell">− {rupees(penaltyCharged)}</td>
          </tr>
        );
      }
    }

    if (!penaltyOpen || penaltyItems.length === 0) return rows;

    rows.push(
      <tr key="penalty-head" className="calc-penalty-detail calc-penalty-detail-head">
        <td colSpan={2}>
          <div className="calc-penalty-line">
            <span>Incident</span><span>Occurrence</span><span>Status</span><span>Amount</span>
          </div>
        </td>
      </tr>
    );

    penaltyItems.forEach((v, i) => {
      const waived = !isPenaltyChargeable(v);
      rows.push(
        <tr key={`penalty-${v.id ?? i}`} className="calc-penalty-detail">
          <td colSpan={2}>
            <div className="calc-penalty-line">
              <span>
                <strong>{v.type}</strong>
                <small>
                  {v.incident_date
                    ? new Date(v.incident_date).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' })
                    : '—'}
                  {v.incident_time ? ` · ${v.incident_time}` : ''}
                </small>
                {v.consequence && <small>{v.consequence}</small>}
                {/* Where it came from, because that decides how it can be
                    removed: the settler's go in one sweep from the LOP
                    register, the app's are tied to a session, and a
                    person's can only be deleted one at a time. Without
                    this, an incident that survived an erase looks like the
                    erase is broken. */}
                <small className="calc-penalty-src">
                  {isSystemAttendance(v) ? 'raised by the settler · erasable from the LOP register'
                    : isSystemLateJoin(v) ? 'measured from the app · API fetch register'
                    : `filed by ${v.reported_by || 'somebody'} · delete it on its own row`}
                </small>
              </span>
              <span>#{v.occurrence_no ?? 1}</span>
              <span>{String(v.status || '').replace(/_/g, ' ')}</span>
              <span className={waived ? 'calc-penalty-waived' : ''}>
                {waived ? 'Waived' : `− ${rupees(v.penalty_amount)}`}
              </span>
            </div>
          </td>
        </tr>
      );
    });

    rows.push(
      <tr key="penalty-foot" className="calc-penalty-detail calc-penalty-detail-foot">
        <td colSpan={2}>
          <div className="calc-penalty-line">
            <span>Recorded incidents total</span><span></span><span></span>
            <span>− {rupees(recordedPenalty)}</span>
          </div>
          {penaltyEdited && (
            <p className="calc-penalty-note">
              <i className="bx bx-error"></i>
              The Penalty input has been changed to {rupees(penaltyTotal)}, so this
              breakdown no longer matches what is being deducted. Clear the input to
              go back to the recorded incidents.
            </p>
          )}
        </td>
      </tr>
    );

    return rows;
  };

  return (
    <div className="pay-calc-grid">
      <div className="pay-calc-col">
        <div className="calc-section-title calc-section-input">
          Input Parameters
          <span>{seed?.coachId ? 'a model — only pay saves' : 'fill these cells only'}</span>
        </div>

        {/* Only the two pay fields write anything. Saying which inputs have
            drifted, and where each one is actually kept, is what stops this
            screen reading as an editor that has lost your changes. */}
        {modelledChanges.length > 0 && (
          <div className="calc-modelling">
            <i className="bx bx-flask"></i>
            <span>
              <strong>
                {modelledChanges.length} input{modelledChanges.length === 1 ? '' : 's'} changed, nothing saved yet
              </strong>
              <small>
                {modelledChanges.map(c => `${c.label} (${c.was} → ${c.now}), edited on ${c.where}`).join('; ')}.
                {onCommitModel
                  ? ' Press Save to the record and they become what the coach is paid on; leave them and they go when you do.'
                  : ' Only Per-Session Rate and Base / Fixed Pay save from here, each with its own button.'}
              </small>
            </span>
            <div className="calc-modelling-acts">
              {onCommitModel && (() => {
                const savable = modelledChanges.filter(c => c.commit);
                return (
                  <button
                    className="btn btn-primary btn-sm"
                    disabled={savable.length === 0}
                    title={savable.length === 0
                      ? 'Nothing here can be written from this screen'
                      : `Write ${savable.length} figure${savable.length === 1 ? '' : 's'} to ${seed.periodMonth}`}
                    onClick={saveModelToRecord}
                  >
                    Save to the record
                  </button>
                );
              })()}
              <button className="btn btn-secondary btn-sm" onClick={resetToRecorded}>
                Reset to recorded
              </button>
            </div>
          </div>
        )}
        {seed?.coachId && seed.coreRecorded === false && (
          <div className="calc-unrated-note">
            <i className="bx bx-error"></i>
            <span>
              <strong>{seed.periodMonth} has no Core Performance ratings.</strong>
              <small>
                Those six cells carry 28% of the score, so it sits at {seed.score ?? 0} and
                the band pays accordingly. They are not entered here — this screen only reads
                the score card. Open {seed.periodMonth} on the Coach Master score card,
                Core Performance tab, and record them there.
              </small>
            </span>
          </div>
        )}
        <table className="data-table calc-table">
          <tbody>
            {/* Which period the figures below belong to. A select wherever the
                caller supplies the months, so another month can be checked
                without leaving the figures; plain text where it does not, and
                then it follows the picker above. Either way it re-seeds from
                that month's score card, so the inputs and the record cannot
                drift apart. */}
            {seed?.periodMonth && inputRow(
              "Performance Period",
              periodOptions?.length && onPeriodChange ? (
                // Changing it re-seeds every figure below from that month's
                // score card, so the pay recalculates for the month chosen.
                <select
                  className="calc-input"
                  value={seed.periodMonth}
                  onChange={(e) => onPeriodChange(e.target.value)}
                >
                  {periodOptions.map(m => <option key={m} value={m}>{m}</option>)}
                </select>
              ) : (
                <span className="calc-static">{seed.periodMonth}</span>
              ),
              seed.periodRange
            )}
            {inputRow("Coach Name", coachOptions ? (
              <select
                className="calc-input calc-input-text"
                value={selectedCoachId ?? ""}
                disabled={lockCoach}
                onChange={(e) => onCoachChange?.(e.target.value)}
              >
                {!lockCoach && <option value="">— Manual entry —</option>}
                {coachOptions.map(c => (
                  <option key={c.id} value={c.id}>{c.name} ({c.id})</option>
                ))}
              </select>
            ) : (
              <input type="text" className="calc-input calc-input-text" value={coachName} placeholder="Enter coach name" onChange={(e) => setCoachName(e.target.value)} />
            ), coachOptions && !lockCoach ? "picking a coach loads their recorded figures" : undefined)}
            {inputRow("Policy Variant", (
              <select className="calc-input" value={variantId} onChange={(e) => setVariantId(e.target.value)}>
                {offeredVariants(variants, variantId).map(v => (
                  <option key={v.id} value={v.id}>{variantLabel(v)}</option>
                ))}
              </select>
            ))}
            {inputRow("Coach Category", (
              <select className="calc-input" value={category} onChange={(e) => setCategory(e.target.value)}>
                {COACH_CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            ), "Fixed / Flexi / Flexi-Fixed")}
            {inputRow("HB+ Benchmark Score", num(score, setScore, 90), "0 – 90")}
            {inputRow("Session Threshold", (
              <input
                type="number" className="calc-input" min="0"
                value={thresholdOverride}
                placeholder={String(pay.defaultThreshold)}
                onChange={(e) => setThresholdOverride(e.target.value)}
              />
            ), pay.thresholdIsOverridden
                 ? `set for this month · the band's own is ${pay.defaultThreshold}`
                 : `blank uses the band's ${pay.defaultThreshold} · extra-session pay starts past this`)}
            {inputRow("Sessions Completed This Month", num(sessions, setSessions))}
            {/* Recorded, not worked out. The threshold asks whether the month
                ran long; this asks how much of it fell outside the hours the
                coach offered, and only the person entering it knows that. */}
            {category === 'Fixed' && inputRow("Sessions Beyond Availability",
              num(beyondSessions, setBeyondSessions),
              pay.beyondAvailabilityOverlap > 0
                ? `⚠ ${pay.beyondAvailabilityOverlap} of these are also past the threshold — those are paid on both lines`
                : `taken outside published hours · paid at ${rupees(pay.beyondAvailabilityRate)} each, on top`)}
            {category === 'Fixed' && inputRow("Beyond-Availability Rate (₹)", (
              <input
                type="number" className="calc-input" min="0"
                value={beyondRate}
                placeholder={String(BEYOND_AVAILABILITY_RATE)}
                onChange={(e) => setBeyondRate(e.target.value)}
              />
            ), beyondRate !== "" && Number(beyondRate) > 0
                 ? 'set on this coach — applies to every month, including settled ones'
                 : `blank uses the standard ${rupees(BEYOND_AVAILABILITY_RATE)}`)}
            {inputRow("Night Sessions Count", num(nightSessions, setNightSessions), "10 PM – 4 AM")}
            {inputRow("5-Star Streak Count", num(streak, setStreak), "consecutive")}
            {/* The consistency bonus is not asked for anywhere. It is
                worked out from the record — 95% attendance, no incidents, no
                missed sessions, no unplanned Loss of Pay — and the figure it
                comes to is on the computed side. Offering it as an input
                invited it to be set, which it never was. */}
            {inputRow("Org Work Pay This Month (₹)", num(orgWorkPay, setOrgWorkPay), "Flexi & Flexi-Fixed only")}
            {inputRow("Missed Sessions", num(missedSessions, setMissedSessions),
              "charged at 1x up to 5, 1.5x up to 10, 2x above")}
            {/* Loss of Pay is not asked for here. It is the count of days
                settled with no login on Attendance & Leave, and it is stated
                on the computed side with what it costs. */}
            {inputRow("Total Penalty (₹)", num(penalties, setPenalties), "recorded incidents; missed sessions are charged separately")}
            {/* Waiving is an input like any other, so it is keyed in on this
                side with them. The breakdown opposite states what was waived
                and what is left to charge, and states it only — one figure is
                either entered or computed, never both. */}
            {canWaive && penaltyTotal > 0 && inputRow("Penalty Waived (₹)",
              num(penaltyWaiver, setPenaltyWaiver, penaltyTotal),
              waived > 0
                ? `${rupees(waived)} forgiven of ${rupees(penaltyTotal)} — the incidents keep their amounts and their place on the ladder`
                : `forgive part or all of the ${rupees(penaltyTotal)} charged — the incidents keep their amounts and their place on the ladder`)}
            {/* Per-session rate applies to every category: Flexi and Flexi-Fixed
                pay it on all sessions, Fixed on the ones beyond its threshold. */}
            {/* Overriding what a coach is paid is a pay decision, not a
                modelling one, so it is left to the roles that own the rate card.
                Everyone else sees the band rate, stated rather than editable. */}
            {inputRow("Per-Session Rate (₹)", (
              !canOverridePay
                ? <span className="calc-static">{rupees(pay.perSessionRate)}</span>
                : unlockedPay.rate
                  ? (
                    <input
                      type="number" min="0" step="any" className="calc-input" value={rateOverride}
                      placeholder={`Std ${rupees(pay.perSessionRate)}`}
                      autoFocus
                      onChange={(e) => setRateOverride(e.target.value)}
                    />
                  )
                  : payLock('rate', 'Per-Session Rate', rupees(pay.perSessionRate),
                      rateOverride !== "" ? rupees(rateOverride) : rupees(pay.perSessionRate))
            ), paySourceHint(seed?.payFrom?.rateFrom, unlockedPay.rate))}
            {/* A Flexi coach has no fixed component — they are paid per session
                alone — so the field is not offered for that category. */}
            {category !== "Flexi" && inputRow("Base / Fixed Pay (₹)", (
              !canOverridePay
                ? <span className="calc-static">{rupees(pay.basePay)}</span>
                : unlockedPay.base
                  ? (
                    <input
                      type="number" min="0" step="any" className="calc-input" value={baseOverride}
                      placeholder={`Std ${rupees(category === 'Fixed' ? rates.std_fixed : rates.min_fixed)}`}
                      autoFocus
                      onChange={(e) => setBaseOverride(e.target.value)}
                    />
                  )
                  : payLock('base', 'Base / Fixed Pay',
                      rupees(category === 'Fixed' ? rates.std_fixed : rates.min_fixed),
                      baseOverride !== "" ? rupees(baseOverride)
                        : rupees(category === 'Fixed' ? rates.std_fixed : rates.min_fixed))
            ), paySourceHint(seed?.payFrom?.fixedFrom, unlockedPay.base))}
          </tbody>
        </table>
        {/* The same action, where the editing is. The banner carrying it sits
            above every field, so it is off screen by the time anyone has
            changed anything. */}
        {onCommitModel && modelledChanges.length > 0 && (() => {
          const savable = modelledChanges.filter(c => c.commit);
          // What this edit looks like. Dismissing the bar hides it for this
          // set of figures; change one again and it comes back.
          const changeKey = modelledChanges.map(c => `${c.label}=${c.now}`).join('|');
          if (savePromptHiddenFor === changeKey) return null;
          return (
            <div className="calc-save-bar">
              <span>
                <strong>
                  {modelledChanges.length} change{modelledChanges.length === 1 ? '' : 's'} not saved
                </strong>
                <small>
                  {savable.length === 0
                    ? 'None of them can be written from this screen — they are worked out elsewhere.'
                    : `${savable.length} of them write to ${seed.periodMonth}.`}
                </small>
              </span>
              <div>
                <button
                  className="btn btn-secondary btn-sm"
                  title="Hide this bar and carry on — your figures stay exactly as you have them"
                  onClick={() => setSavePromptHiddenFor(changeKey)}
                >
                  Cancel
                </button>
                <button
                  className="btn btn-secondary btn-sm"
                  title="Put every figure back to what is recorded, throwing away what you have typed"
                  onClick={resetToRecorded}
                >
                  Reset
                </button>
                <button
                  className="btn btn-primary btn-sm"
                  disabled={savable.length === 0}
                  title={savable.length === 0
                    ? 'Nothing here can be written from this screen'
                    : `Write ${savable.length} figure${savable.length === 1 ? '' : 's'} to ${seed.periodMonth}`}
                  onClick={saveModelToRecord}
                >
                  Save to the record
                </button>
              </div>
            </div>
          );
        })()}
        {canOverridePay && onSavePayOverrides && seed?.coachId && (() => {
          const savedBase = seed.baseOverride === "" || seed.baseOverride == null
            ? null : Number(seed.baseOverride);
          const savedRate = seed.rateOverride === "" || seed.rateOverride == null
            ? null : Number(seed.rateOverride);
          const nextBase = baseOverride === "" ? null : Number(baseOverride);
          const nextRate = rateOverride === "" ? null : Number(rateOverride);
          if (nextBase === savedBase && nextRate === savedRate) return null;

          const describe = (value, what) => value === null
            ? `${what} back to the band rate`
            : `${what} ${rupees(value)}`;
          const changes = [
            nextBase !== savedBase ? describe(nextBase, 'base pay') : null,
            nextRate !== savedRate ? describe(nextRate, 'per-session rate') : null
          ].filter(Boolean);

          return (
            <div className="calc-save-override">
              <i className="bx bx-lock-open-alt"></i>
              <span>
                <strong>Not saved yet</strong>
                <small>
                  This only models {seed.periodMonth} until it is saved —
                  setting {changes.join(' and ')} for {seed.coachName || 'this coach'}.
                  {seed.periodMonth} and the months after it carry these figures;
                  earlier months are untouched.
                </small>
              </span>
              <button
                className="btn btn-primary btn-sm"
                onClick={() => onSavePayOverrides(seed.coachId, seed.periodMonth, { base: nextBase, rate: nextRate })}
              >
                Save {seed.periodMonth}
              </button>
            </div>
          );
        })()}
      </div>

      <div className="pay-calc-col">
        <div className="calc-section-title calc-section-output">Computed Pay Breakdown <span>{band.label}</span></div>
        <table className="data-table calc-table">
          <tbody>
            {outputRow("Base / Fixed Pay (₹)", rupees(pay.basePay),
              category === 'Flexi' ? "not paid to Flexi" : (baseOverride !== "" ? "entered above" : null))}
            {outputRow("Per-Session Rate (₹)", rupees(pay.perSessionRate),
              rateOverrideNum !== null ? "entered above" : null)}
            {outputRow("Sessions for the month", Number(sessions) || 0)}
            {outputRow("Extra Sessions (beyond threshold)", pay.extraSessions,
              category === 'Fixed'
                ? `${Number(sessions) || 0} completed − ${pay.threshold} threshold`
                : "Fixed only — the flexible categories are paid per session")}
            {outputRow("Extra-Session Pay (₹)", rupees(pay.extraSessionPay),
              category === 'Fixed'
                ? (pay.extraSessionPay === 0 && pay.extraSessions > 0
                    ? `${pay.extraSessions} × ${rupees(pay.perSessionRate)} withheld — 0–30 Non-Functional is fixed pay only`
                    : `${pay.extraSessions} × ${rupees(pay.perSessionRate)}`)
                : "Fixed only")}
            {outputRow("Sessions Beyond Availability", pay.beyondAvailabilitySessions,
              category === 'Fixed'
                ? "taken outside published hours — keyed in on the left, not worked out"
                : "Fixed only")}
            {outputRow("Beyond-Availability Pay (₹)", rupees(pay.beyondAvailabilityPay),
              pay.beyondAvailabilitySessions > 0
                ? `${pay.beyondAvailabilitySessions} × ${rupees(pay.beyondAvailabilityRate)}, on top of the salary`
                : null)}
            {pay.beyondAvailabilityOverlap > 0 && outputRow(
              "⚠ Counted on both lines",
              pay.beyondAvailabilityOverlap,
              `up to ${pay.beyondAvailabilityOverlap} session(s) are past the threshold AND outside the offered `
                + `hours, so they are paid twice — once at ${rupees(pay.perSessionRate)}, once at `
                + `${rupees(pay.beyondAvailabilityRate)}. Lower one of the two counts if that is not intended.`)}
            {outputRow("Session Threshold", pay.threshold,
              pay.thresholdIsOverridden ? "set for this month" : null)}

            {/* Only Flexi and Flexi-Fixed are paid per session on every session;
                for Fixed the row is always ₹0, so it is not shown. */}
            {category !== "Fixed" && outputRow("Per-Session Pay (₹)", rupees(pay.sessionPay))}
            {outputRow("Night Session Premium (₹)", rupees(pay.nightSessionPay), "₹60/session, Flexi & Flexi-Fixed only")}
            {outputRow("Milestone Incentive (₹)", rupees(pay.milestoneIncentive))}
            {outputRow("Consistency Bonus (₹)", rupees(pay.consistencyBonus))}
            {outputRow("5-Star Streak Bonus (₹)", rupees(pay.streakBonusPay), `₹${vConfig.id === 'V3' ? 500 : 200} per ${vConfig.id === 'V3' ? 15 : 10} consecutive`)}
            {outputRow("Org Work Pay (₹)", rupees(pay.orgWorkPay), "Flexi & Flexi-Fixed only")}
            {Number(missedSessions) > 0 && outputRow(
              "Missed Session Penalty (₹)",
              `− ${rupees(pay.missedSessionDeduction)}`,
              `${pay.missedSessionMultiplier}× × ${pay.missedSessions} × ${rupees(pay.missedSessionRate)}` +
                (category === 'Fixed' ? ' — fixed pay ÷ 26 ÷ 5' : '')
            )}
            {penaltyRow()}
            {/* Under the penalty, because it is the other thing that comes
                off the month and the two are read together. Always drawn:
                "no days lost" is an answer, and its absence was being read
                as the figure not having been worked out. */}
            {outputRow(
              "Loss of Pay (days)",
              pay.lopDays || 0,
              'days settled with no login — recorded on Attendance & Leave'
            )}
            {outputRow(
              "Loss of Pay (₹)",
              pay.lossOfPay > 0 ? `− ${rupees(pay.lossOfPay)}` : rupees(0),
              category === 'Flexi'
                ? 'a Flexi coach has no base pay to deduct from — recorded only'
                : pay.lopDays > 0
                  ? `${pay.lopDays} day(s) × ${rupees(lopPerDayHere)} — base pay ÷ 26`
                  : `${rupees(lopPerDayHere)} a day — base pay ÷ 26, if any are lost`
            )}
            {outputRow("Gross Monthly Pay (₹)", rupees(grossPay), null, true)}
            {outputRow("Income Tax u/s 194J (₹)", `− ${rupees(incomeTax)}`, "10% TDS on professional fees")}
            {outputRow("Net Monthly Pay (₹)", rupees(netPay), "what reaches the coach", true)}
          </tbody>
        </table>
        {forecastNow && (
          <div className="calc-forecast">
            <div className="calc-forecast-head">
              Benchmark &amp; Forecast <span>does not affect pay</span>
            </div>
            <table className="data-table calc-table">
              <tbody>
                {(() => {
                  const m = category === 'Flexi'
                    ? null : against(pay.basePay, forecastNow.salaryLo, forecastNow.salaryHi);
                  return (
                    <tr className={m ? `bench-row bench-${m.state}` : ''}>
                      <td className="calc-label">
                        Benchmark Salary (₹)
                        <span className="calc-hint">
                          the band's range — {band.label}
                          {m && <> · paid {rupees(pay.basePay)}, <strong>{m.label}</strong></>}
                        </span>
                      </td>
                      <td className="calc-output-cell">
                        {forecastNow.salaryHi > forecastNow.salaryLo
                          ? `${rupees(forecastNow.salaryLo)} – ${rupees(forecastNow.salaryHi)}`
                          : rupees(forecastNow.salaryLo)}
                      </td>
                    </tr>
                  );
                })()}
                {(() => {
                  const m = against(pay.perSessionRate, forecastNow.rateLo, forecastNow.rateHi);
                  return (
                    <tr className={m ? `bench-row bench-${m.state}` : ''}>
                      <td className="calc-label">
                        Benchmark Per Session (₹)
                        <span className="calc-hint">
                          {category === 'Fixed'
                            ? 'across that range, ÷ 26 ÷ 6, floored at ₹200'
                            : "the band's session rate"}
                          {m && <> · paid {rupees(pay.perSessionRate)}, <strong>{m.label}</strong></>}
                        </span>
                      </td>
                      <td className="calc-output-cell">
                        {forecastNow.rateHi > forecastNow.rateLo
                          ? `${rupees(forecastNow.rateLo)} – ${rupees(forecastNow.rateHi)}`
                          : rupees(forecastNow.rateLo)}
                      </td>
                    </tr>
                  );
                })()}
                <tr>
                  <td className="calc-label">
                    Forecast Fixed Pay (₹)
                    <span className="calc-hint">on this month's score — {band.label}</span>
                  </td>
                  <td className="calc-output-cell">{rupees(forecastNow.base)}</td>
                </tr>
                <tr>
                  <td className="calc-label">
                    Forecast Per-Session Rate (₹)
                    <span className="calc-hint">
                      {category === 'Fixed' ? 'forecast fixed pay ÷ 26 ÷ 6' : `band rate for ${band.label}`}
                    </span>
                  </td>
                  <td className="calc-output-cell">{rupees(forecastNow.rate)}</td>
                </tr>
                {forecastNext ? (
                  <>
                    <tr>
                      <td className="calc-label">
                        Next Band Fixed Pay (₹)
                        <span className="calc-hint">if the score reaches {forecastNext.label}</span>
                      </td>
                      <td className="calc-output-cell">{rupees(forecastNext.base)}</td>
                    </tr>
                    <tr>
                      <td className="calc-label">
                        Next Band Per-Session Rate (₹)
                        <span className="calc-hint">
                          + {rupees(forecastNext.base - forecastNow.base)} a month on the fixed component
                        </span>
                      </td>
                      <td className="calc-output-cell">{rupees(forecastNext.rate)}</td>
                    </tr>
                  </>
                ) : (
                  <tr>
                    <td className="calc-label" colSpan={2}>
                      <span className="calc-hint">Already in the top band — nothing above this one.</span>
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        )}

        <p className="calc-notes">
          Night premium is ₹60/session for Flexi &amp; Flexi-Fixed only. Milestone slabs: Fixed 156 → ₹1,000, 182 → ₹2,000; Flexi / Flexi-Fixed 96 → ₹1,152, 135 → ₹2,025, 186 → ₹3,640.
          Consistency bonus is ₹500, worked out from the record: 95% attendance, no incidents, no missed sessions and no unplanned Loss of Pay. The 5-star streak resets on any violation or no-show.
        </p>
      </div>
    </div>
  );
}

/**
 * The bar at the top of a screen: what it is for, and what it writes.
 *
 * Three kinds of screen live in this app and they look identical — ones that
 * record, ones that only work something out, and ones that read back. Saying
 * which, in a line, is what stops somebody filling in a calculator and
 * hunting for the Save button that was never going to be there.
 */
function ViewPurpose({ title, does, writes, children }) {
  return (
    <div className="view-purpose">
      <div>
        <h2>{title}</h2>
        <p>{does}</p>
      </div>
      <div className="view-purpose-side">
        <span className={`writes-badge writes-${writes.kind}`}>
          {writes.kind === 'records' ? 'Records' : writes.kind === 'reads' ? 'Read only' : 'Works it out'}
        </span>
        <small>{writes.detail}</small>
        {children}
      </div>
    </div>
  );
}

/**
 * Task tabs for a screen that answers more than one question.
 *
 * Attendance & Leave was eleven cards on one scroll, and finding anything
 * meant reading past the ten you did not want. These are the jobs people
 * arrive with, not the tables the data sits in.
 */
function TaskTabs({ tabs, active, onChange }) {
  return (
    <div className="task-tabs" role="tablist">
      {tabs.map(t => (
        <button
          key={t.key}
          role="tab"
          aria-selected={active === t.key}
          className={`task-tab ${active === t.key ? 'task-tab-on' : ''}`}
          onClick={() => onChange(t.key)}
        >
          <i className={`bx ${t.icon}`}></i>
          <span>{t.label}</span>
          {t.count > 0 && <span className="task-tab-count">{t.count}</span>}
        </button>
      ))}
    </div>
  );
}

/** Compensation reference tables A–E, rendered from the selected policy variant. */
function PayReferenceTables({ vConfig, penaltyMatrix }) {
  if (!vConfig) return null;
  const rateFor = (category, band) => vConfig.rates[category]?.[band.label] || {};
  const milestones = vConfig.milestones || {};
  const rules = penaltyMatrix[vConfig.id] || penaltyMatrix['default'] || {};

  const milestoneRow = (category) => {
    const list = milestones[category] || [];
    return (
      <tr key={category}>
        <td><strong>{category}</strong></td>
        {[0, 1, 2].flatMap(i => [
          <td key={`s${i}`} className="num-col">{list[i] ? list[i].threshold : '—'}</td>,
          <td key={`p${i}`} className="num-col">{list[i] ? rupees(list[i].amount) : '—'}</td>
        ])}
      </tr>
    );
  };

  return (
    <>
      <div className="card">
        <div className="card-header-row"><h3>A — Fixed Coaches</h3></div>
        <div className="table-container">
          <table className="data-table reference-table">
            <thead>
              <tr>
                <th>HB+ Benchmark</th><th className="num-col">Per-Session (₹)</th><th className="num-col">Band Variation %</th>
                <th className="num-col">Std Fixed Salary (₹)</th><th className="num-col">Min Salary (₹)</th><th className="num-col">Max Salary (₹)</th>
                <th>Performance Meaning</th><th>Notes</th>
              </tr>
            </thead>
            <tbody>
              {PAY_BANDS.map(b => {
                const r = rateFor("Fixed", b);
                return (
                  <tr key={b.label}>
                    <td><strong>{b.short}</strong></td>
                    <td className="num-col">{rupees(r.per_session)}</td>
                    <td className="num-col">{b.variation}</td>
                    <td className="num-col">{rupees(r.std_fixed)}</td>
                    <td className="num-col">{rupees(r.min_fixed)}</td>
                    <td className="num-col">{rupees(r.max_fixed)}</td>
                    <td>{b.meaning}</td>
                    <td className="text-muted">{b.note}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      <div className="card">
        <div className="card-header-row"><h3>B — Flexi Coaches <span className="text-muted">(per-session + milestone only)</span></h3></div>
        <div className="table-container">
          <table className="data-table reference-table">
            <thead>
              <tr>
                <th>HB+ Benchmark</th><th className="num-col">Per-Session (₹)</th><th className="num-col">Session Threshold</th>
                <th className="num-col">Night Premium (₹)</th><th>Performance Meaning</th><th>Notes</th>
              </tr>
            </thead>
            <tbody>
              {PAY_BANDS.map(b => {
                const r = rateFor("Flexi", b);
                return (
                  <tr key={b.label}>
                    <td><strong>{b.short}</strong></td>
                    <td className="num-col">{rupees(r.per_session)}</td>
                    <td className="num-col">{r.threshold ?? 96}</td>
                    <td className="num-col">₹60</td>
                    <td>{b.meaning}</td>
                    <td className="text-muted">{b.label === PAY_BANDS[0].label ? 'No fixed pay; per session only' : ''}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      <div className="card">
        <div className="card-header-row"><h3>C — Flexi-Fixed Coaches <span className="text-muted">(fixed pay + per-session)</span></h3></div>
        <div className="table-container">
          <table className="data-table reference-table">
            <thead>
              <tr>
                <th>HB+ Benchmark</th><th className="num-col">Per-Session (₹)</th><th className="num-col">Fixed Pay Min (₹)</th>
                <th className="num-col">Fixed Pay Max (₹)</th><th className="num-col">Session Threshold</th>
                <th className="num-col">Night Premium (₹)</th><th>Performance Meaning</th><th>Org Work Eligible</th>
              </tr>
            </thead>
            <tbody>
              {PAY_BANDS.map(b => {
                const r = rateFor("Flexi-Fixed", b);
                return (
                  <tr key={b.label}>
                    <td><strong>{b.short}</strong></td>
                    <td className="num-col">{rupees(r.per_session)}</td>
                    <td className="num-col">{rupees(r.min_fixed)}</td>
                    <td className="num-col">{rupees(r.max_fixed)}</td>
                    <td className="num-col">{r.threshold ?? 96}</td>
                    <td className="num-col">₹60</td>
                    <td>{b.meaning}</td>
                    <td><span className="badge badge-success">Yes</span></td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      <div className="card">
        <div className="card-header-row"><h3>Organizational Work Pay <span className="text-muted">(Flexi &amp; Flexi-Fixed only)</span></h3></div>
        <div className="table-container">
          <table className="data-table reference-table">
            <thead>
              <tr><th>Work Type</th><th>Effort</th><th>Knowledge</th><th className="num-col">Min (₹)</th><th className="num-col">Max (₹)</th><th>Notes</th></tr>
            </thead>
            <tbody>
              {ORG_WORK_REFERENCE.map(w => (
                <tr key={w.type}>
                  <td><strong>{w.type}</strong></td>
                  <td>{w.effort}</td>
                  <td>{w.knowledge}</td>
                  <td className="num-col">{rupees(w.min)}</td>
                  <td className="num-col">{rupees(w.max)}</td>
                  <td className="text-muted">{w.note}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <div className="card">
        <div className="card-header-row"><h3>D — Milestone Rewards <span className="text-muted">(session-based)</span></h3></div>
        <div className="table-container">
          <table className="data-table reference-table">
            <thead>
              <tr>
                <th>Category</th><th className="num-col">MS1 Sessions</th><th className="num-col">MS1 Pay (₹)</th>
                <th className="num-col">MS2 Sessions</th><th className="num-col">MS2 Pay (₹)</th>
                <th className="num-col">MS3 Sessions</th><th className="num-col">MS3 Pay (₹)</th>
              </tr>
            </thead>
            <tbody>{COACH_CATEGORIES.map(milestoneRow)}</tbody>
          </table>
        </div>
      </div>

      <div className="card">
        <div className="card-header-row"><h3>E — Annexure-1 Violation Penalties</h3></div>
        <div className="table-container">
          <table className="data-table reference-table">
            <thead>
              <tr><th>Violation Type</th><th>1st</th><th>2nd</th><th>3rd</th><th>4th / Final</th></tr>
            </thead>
            <tbody>
              {Object.entries(rules).map(([type, tiers]) => (
                <tr key={type}>
                  <td><strong>{type}</strong></td>
                  {[0, 1, 2, 3].map(i => (
                    <td key={i}>{tiers[i] ? tiers[i].consequence : '—'}</td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </>
  );
}

// Brand-guideline colours. These sit behind white pill text, so each is taken
// at a depth that still carries the label — the lighter cream, tan and sage
// from the palette are used elsewhere, not here.
// The coach page reads as three separate records — who they are, where they
// are paid, and what they bring — so it is tabbed rather than stacked.
// The coach record, grouped the way someone looks for it rather than the way
// it is stored: what they scored, what they are paid, when they were away,
// what was logged against them, and the standing facts behind all four.
// Overview answers the common question without opening any of the others.
const COACH_DETAIL_TABS = [
  { key: 'overview',  label: 'Overview',           tone: 'teal' },
  { key: 'scorecard', label: 'Score card',         tone: 'violet' },
  { key: 'pay',       label: 'Pay & payslips',     tone: 'blue',   pay: true },
  { key: 'leave',     label: 'Leave & attendance', tone: 'indigo' },
  { key: 'incidents', label: 'Incidents',          tone: 'amber' },
  { key: 'details',   label: 'Profile',            tone: 'teal' }
];

// Section 194J of the Income Tax Act: 10% withheld at source on professional
// and technical fees, which is how a coach's remuneration is treated.
const TDS_194J_RATE = 0.10;

const TAB_TONE_COLORS = {
  blue: "#344161",   // navy (secondary)
  amber: "#a9674d",  // terracotta (primary)
  violet: "#53372b", // brown (primary)
  indigo: "#414e6d", // navy, one step up
  red: "#9f4022",    // rust (primary)
  teal: "#747440",   // olive (primary)
  green: "#5c7a68"   // sage, deepened for white text
};

/**
 * Score Management tab bar. A single highlight slides between tabs and morphs
 * colour rather than snapping, so moving across groups reads as one continuous
 * motion instead of seven separate buttons lighting up.
 */
function ScorecardTabs({ groups, active, onChange, weights }) {
  const listRef = useRef(null);
  const tabRefs = useRef({});
  const [pill, setPill] = useState(null);

  useLayoutEffect(() => {
    const measure = () => {
      const el = tabRefs.current[active];
      const list = listRef.current;
      if (!el || !list) return;
      setPill({
        left: el.offsetLeft - list.scrollLeft,
        top: el.offsetTop,
        width: el.offsetWidth,
        height: el.offsetHeight
      });
    };
    measure();
    window.addEventListener('resize', measure);
    return () => window.removeEventListener('resize', measure);
  }, [active, groups.length]);

  const tone = groups.find(g => g.key === active)?.tone;

  return (
    <div className="scorecard-tabs" role="tablist" ref={listRef}>
      {pill && (
        <span
          className="scorecard-tab-pill"
          aria-hidden="true"
          style={{
            transform: `translate(${pill.left}px, ${pill.top}px)`,
            width: `${pill.width}px`,
            height: `${pill.height}px`,
            backgroundColor: TAB_TONE_COLORS[tone] || 'var(--accent-teal)'
          }}
        />
      )}
      {groups.map(group => {
        const hasWeights = weights && Object.keys(weights).length > 0;
        const gw = group.weightKeys && hasWeights
          ? group.weightKeys.reduce((sum, k) => sum + (weights[k] || 0), 0)
          : null;
        return (
          <button
            key={group.key}
            ref={(el) => { tabRefs.current[group.key] = el; }}
            role="tab"
            aria-selected={active === group.key}
            className={`scorecard-tab ${active === group.key ? 'active' : ''}`}
            onClick={() => onChange(group.key)}
          >
            {group.label}
            {gw !== null && <span className="scorecard-tab-weight">Wt {gw}%</span>}
          </button>
        );
      })}
    </div>
  );
}

